  // a primitive result that no library call returned
  //   assert monomial_div((3, 4, 1), (1, 2, 0)) == (2, 2, 1)
  //   => (2, 2, 1)
  it.todo("test_monomial_div:184");
  // a primitive result that no library call returned
  //   assert monomial_gcd((3, 4, 1), (1, 2, 0)) == (1, 2, 0)
  //   => (1, 2, 0)
  it.todo("test_monomial_gcd:187");
  // a primitive result that no library call returned
  //   assert monomial_lcm((3, 4, 1), (1, 2, 0)) == (3, 4, 1)
  //   => (3, 4, 1)
  it.todo("test_monomial_lcm:190");
  // a primitive result that no library call returned
  //   assert monomial_max((3, 4, 5), (0, 5, 1), (6, 3, 9)) == (6, 5, 9)
  //   => (6, 5, 9)
  it.todo("test_monomial_max:193");
  // a primitive result that no library call returned
  //   assert monomial_pow((1, 2, 3), 3) == (3, 6, 9)
  //   => (3, 6, 9)
  it.todo("test_monomial_pow:196");
  // a primitive result that no library call returned
  //   assert monomial_min((3, 4, 5), (0, 5, 1), (6, 3, 9)) == (0, 3, 1)
  //   => (0, 3, 1)
  it.todo("test_monomial_min:199");
  it("test_monomial_divides:202", () => {
    expect(sympyStr(monomialDivides([1, 2, 3], [4, 5, 6]))).toBe('True');
  });
  it("test_monomial_divides:203", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  // the printed result differs (false)
  //   assert m == (3, 4, 1)
  //   => (3, 4, 1)
  it.todo("test_Monomial:221");
  it("test_Monomial:222", () => {
    const [x, y, z] = symbols('x y z');
    expect(sympyStr(new Monomial([1, 2, 0], [x, y, z]))).not.toBe('(3, 4, 1)');
  });
  it("test_Monomial:223", () => {
    const [x, y, z] = symbols('x y z');
    expect(sympyStr(new Monomial([3, 4, 1], [x, y, z]))).not.toBe('(1, 2, 0)');
  });
  // the printed result differs (false)
  //   assert n == (1, 2, 0)
  //   => (1, 2, 0)
  it.todo("test_Monomial:224");
  it.fails("test_Monomial:256", () => {
    expect(sympyStr(new Monomial([0, 0, 0]))).toBe('x**0*y**0*z**0');
  });
  it("test_Monomial:263", () => {
    const unicode = pprintUseUnicode(false);
    try {
      expect(pyStr(new Monomial([1, 2, 3]))).toBe('Monomial((1, 2, 3))');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
  it("test_Monomial:264", () => {
    const [x, y, z] = symbols('x y z');
    const unicode = pprintUseUnicode(false);
    try {
      expect(pyStr(new Monomial([3, 4, 1], [x, y, z]))).toBe('x**3*y**4*z**1');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
